import java.nio.ByteBuffer;
import java.nio.charset.StandardCharsets;

private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    while (bb.hasRemaining()) {
        int b = bb.get() & 0xFF;
        if ((b & 0x80) == 0) {
            sb.append((char) b);
            i++;
        } else if ((b & 0xE0) == 0xC0) {
            if (!bb.hasRemaining()) break;
            int b1 = bb.get() & 0xFF;
            sb.append((char) ((b & 0x1F) << 6 | (b1 & 0x3F)));
            i += 2;
        } else if ((b & 0xF0) == 0xE0) {
            if (bb.remaining() < 2) break;
            int b1 = bb.get() & 0xFF;
            int b2 = bb.get() & 0xFF;
            sb.append((char) ((b & 0x0F) << 12 | (b1 & 0x3F) << 6 | (b2 & 0x3F)));
            i += 3;
        } else if ((b & 0xF8) == 0xF0) {
            if (bb.remaining() < 3) break;
            int b1 = bb.get() & 0xFF;
            int b2 = bb.get() & 0xFF;
            int b3 = bb.get() & 0xFF;
            int codePoint = ((b & 0x07) << 18 | (b1 & 0x3F) << 12 | (b2 & 0x3F) << 6 | (b3 & 0x3F));
            if (codePoint <= 0xFFFF) {
                sb.append((char) codePoint);
            } else {
                codePoint -= 0x10000;
                sb.append((char) (0xD800 | (codePoint >> 10)));
                sb.append((char) (0xDC00 | (codePoint & 0x3FF)));
            }
            i += 4;
        } else {
            // Invalid UTF-8 sequence
            break;
        }
    }
    return i;
}
