import java.io.File;
import java.io.IOException;

public class FileDeletionUtility {

    /** 
     * Schedules a file to be deleted when JVM exits. If file is directory delete it and all sub-directories.
     * @param file  file or directory to delete, must not be {@code null}
     * @throws NullPointerException if the file is {@code null}
     * @throws IOException in case deletion is unsuccessful
     */
    public static void forceDeleteOnExit(File file) throws IOException {
        if (file == null) {
            throw new NullPointerException("File must not be null");
        }
        if (file.isDirectory()) {
            deleteDirectoryOnExit(file);
        } else {
            file.deleteOnExit();
        }
    }

    private static void deleteDirectoryOnExit(File directory) throws IOException {
        File[] files = directory.listFiles();
        if (files != null) {
            for (File file : files) {
                if (file.isDirectory()) {
                    deleteDirectoryOnExit(file);
                } else {
                    file.deleteOnExit();
                }
            }
        }
        directory.deleteOnExit();
    }

    public static void main(String[] args) {
        // Example usage
        File tempFile = new File("tempFile.txt");
        try {
            tempFile.createNewFile();
            forceDeleteOnExit(tempFile);
        } catch (IOException e) {
            e.printStackTrace();
        }

        File tempDir = new File("tempDir");
        tempDir.mkdirs();
        File tempSubFile = new File(tempDir, "tempSubFile.txt");
        try {
            tempSubFile.createNewFile();
            forceDeleteOnExit(tempDir);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}
