public class LogTableHandler extends Handler {

    private final JTextArea logTextArea;

    public LogTableHandler(JTextArea logTextArea) {
        this.logTextArea = logTextArea;
    }

    @Override
    public void publish(LogRecord lr) {
        addMessage(lr);
    }

    @Override
    public void flush() {
        // Flush implementation if necessary
    }

    @Override
    public void close() throws SecurityException {
        // Close implementation if necessary
    }

    /**
     * Add a log record message to be displayed in the LogTable. This method is thread-safe as it posts requests to the SwingThread rather than processing directly.
     */
    public void addMessage(final LogRecord lr) {
        SwingUtilities.invokeLater(new Runnable() {
            @Override
            public void run() {
                logTextArea.append(lr.getMessage() + "\n");
            }
        });
    }

    public static void main(String[] args) {
        JTextArea logTextArea = new JTextArea();
        Logger logger = LogManager.getLogManager().getLogger(Logger.GLOBAL_LOGGER_NAME);
        logger.addHandler(new LogTableHandler(logTextArea));

        JFrame frame = new JFrame("Log Table Example");
        frame.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
        frame.add(new JScrollPane(logTextArea));
        frame.setSize(400, 300);
        frame.setVisible(true);

        logger.info("This is a log message.");
    }
