import org.jgrapht.Graph;
import org.jgrapht.graph.DefaultEdge;
import org.jgrapht.generate.BipartiteGraphGenerator;
import org.jgrapht.generate.SimpleGraphGeneratorBase;

import java.util.HashMap;
import java.util.Map;

public class CompleteBipartiteGraphGenerator<V, E extends DefaultEdge> extends SimpleGraphGeneratorBase<V, E> {

    private int numberOfVerticesPart1;
    private int numberOfVerticesPart2;

    public CompleteBipartiteGraphGenerator(int numberOfVerticesPart1, int numberOfVerticesPart2) {
        this.numberOfVerticesPart1 = numberOfVerticesPart1;
        this.numberOfVerticesPart2 = numberOfVerticesPart2;
    }

    @Override
    public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
        if (resultMap == null) {
            resultMap = new HashMap<>();
        }

        // Add vertices to the first partition
        for (int i = 0; i < numberOfVerticesPart1; i++) {
            V vertex = target.addVertex();
            resultMap.put("part1_" + i, vertex);
        }

        // Add vertices to the second partition
        for (int i = 0; i < numberOfVerticesPart2; i++) {
            V vertex = target.addVertex();
            resultMap.put("part2_" + i, vertex);
        }

        // Connect each vertex in the first partition to each vertex in the second partition
        for (int i = 0; i < numberOfVerticesPart1; i++) {
            for (int j = 0; j < numberOfVerticesPart2; j++) {
                V vertexFromPart1 = resultMap.get("part1_" + i);
                V vertexFromPart2 = resultMap.get("part2_" + j);
                target.addEdge(vertexFromPart1, vertexFromPart2);
            }
        }
    }
}
