public class MetricsCache<METRICS extends Map<String, Integer>> {
    private METRICS cache;

    public MetricsCache() {
        this.cache = (METRICS) new HashMap<String, Integer>();
    }

    @Override
    public void accept(final METRICS data) {
        if (data != null) {
            for (Map.Entry<String, Integer> entry : data.entrySet()) {
                cache.merge(entry.getKey(), entry.getValue(), Integer::sum);
            }
        }
    }

    public METRICS getCache() {
        return cache;
    }

    public static void main(String[] args) {
        MetricsCache<HashMap<String, Integer>> metricsCache = new MetricsCache<>();
        HashMap<String, Integer> data = new HashMap<>();
        data.put("metric1", 10);
        data.put("metric2", 20);
        metricsCache.accept(data);

        System.out.println(metricsCache.getCache());
    }
}
