import java.util.LinkedList;

class Bucket {
    private LinkedList<Bucket> list;
    private Bucket next;

    public Bucket(LinkedList<Bucket> list) {
        this.list = list;
    }

    /** 
     * Inserts this bucket in the data structure before the  {@code bucket}.
     * @param bucket the bucket, that will be the next to this bucket.
     */
    void insertBefore(Bucket bucket) {
        if (bucket != null && list != null) {
            int index = list.indexOf(bucket);
            if (index != -1) {
                list.add(index, this);
            }
        }
    }

    public void setNext(Bucket next) {
        this.next = next;
    }

    public Bucket getNext() {
        return next;
    }
}
