import java.nio.charset.StandardCharsets;

public class UTF8SizeCalculator {

    /** 
     * Computes the size of the utf8 string beginning at the specified  {@code index} with the specified {@code length}.
     */
    public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
        if (str == null) {
            throw new IllegalArgumentException("CharSequence cannot be null");
        }
        if (index < 0 || len < 0 || index + len > str.length()) {
            throw new IndexOutOfBoundsException("Invalid index or length");
        }

        int size = 0;
        for (int i = index; i < index + len; i++) {
            char ch = str.charAt(i);
            if (ch <= 0x7F) {
                size += 1;
            } else if (ch <= 0x7FF) {
                size += 2;
            } else if (Character.isSurrogate(ch)) {
                size += 4; // surrogate pair
                i++; // skip the next char as it's part of the surrogate pair
            } else {
                size += 3;
            }
        }
        return size;
    }

    public static void main(String[] args) {
        CharSequence str = "Hello, World!";
        int index = 0;
        int len = str.length();
        System.out.println("UTF8 Size: " + computeUTF8Size(str, index, len));
    }
}
