import java.util.HashSet;
import java.util.Set;

public class Graph<V, E> {
    private Set<E> edges;

    // Assuming each edge has a method to get its source and target vertices
    public interface Edge<V> {
        V getSource();
        V getTarget();
    }

    public Graph(Set<E> edges) {
        this.edges = edges;
    }

    private Set<V> initVisibleVertices() {
        Set<V> visibleVertices = new HashSet<>();
        for (E edge : edges) {
            visibleVertices.add(((Edge<V>) edge).getSource());
            visibleVertices.add(((Edge<V>) edge).getTarget());
        }
        return visibleVertices;
    }

    public static void main(String[] args) {
        // Example usage
        Set<Edge<String>> edges = new HashSet<>();
        edges.add(new Edge<String>() {
            @Override
            public String getSource() {
                return "A";
            }
            @Override
            public String getTarget() {
                return "B";
            }
        });
        edges.add(new Edge<String>() {
            @Override
            public String getSource() {
                return "B";
            }
            @Override
            public String getTarget() {
                return "C";
            }
        });

        Graph<String, Edge<String>> graph = new Graph<>(edges);
        System.out.println(graph.initVisibleVertices()); // Output: [A, B, C]
    }
}
