import java.util.Objects;

public class StringUtils {
    /** 
     * Gets a substring from the specified String avoiding exceptions. 
     */
    public static String sub(String str, int start, int end) {
        if (str == null) {
            return null;
        }
        if (start < 0) {
            start = 0;
        }
        if (end > str.length()) {
            end = str.length();
        }
        if (start > end) {
            return "";
        }
        return str.substring(start, end);
    }

    public static void main(String[] args) {
        System.out.println(sub("Hello, World!", 7, 12)); // Output: World
        System.out.println(sub("Hello, World!", 0, 5));  // Output: Hello
        System.out.println(sub("Hello, World!", 15, 20)); // Output: (empty string)
        System.out.println(sub(null, 1, 3));            // Output: null
        System.out.println(sub("Hello", -1, 3));         // Output: Hel
        System.out.println(sub("Hello", 3, 1));          // Output: (empty string)
    }
}
