import java.util.LinkedList;

public class Edge {
    private LinkedList<Edge> treeEdgesList1;
    private LinkedList<Edge> treeEdgesList2;

    public Edge(LinkedList<Edge> treeEdgesList1, LinkedList<Edge> treeEdgesList2) {
        this.treeEdgesList1 = treeEdgesList1;
        this.treeEdgesList2 = treeEdgesList2;
    }

    /** 
     * Removes this edge from both doubly linked lists of tree edges.
     */
    public void removeFromTreeEdgeList() {
