        treeEdgesList2.remove(this);
    }

    public static void main(String[] args) {
        LinkedList<Edge> list1 = new LinkedList<>();
        LinkedList<Edge> list2 = new LinkedList<>();

        Edge edge = new Edge(list1, list2);
        list1.add(edge);
        list2.add(edge);

        System.out.println("Before removal: List1 contains edge? " + list1.contains(edge));
        System.out.println("Before removal: List2 contains edge? " + list2.contains(edge));

        edge.removeFromTreeEdgeList();

        System.out.println("After removal: List1 contains edge? " + list1.contains(edge));
        System.out.println("After removal: List2 contains edge? " + list2.contains(edge));
    }
