import java.util.Properties;

public class PropertySubstitutor {
    public static String findAndSubst(String key, Properties props) {
        String value = props.getProperty(key);
        if (value == null) {
            return null;
        }
        // Simple variable substitution example: assuming variables are in the form ${varName}
        return value.replaceAll("\\$\\{(\\w+)\\}", (match) -> {
            String varName = match.group(1);
            String varValue = props.getProperty(varName);
            return varValue != null ? varValue : match.group(0);
        });
    }

    public static void main(String[] args) {
        Properties props = new Properties();
        props.setProperty("greeting", "Hello, ${name}!");
        props.setProperty("name", "World");

        String result = findAndSubst("greeting", props);
        System.out.println(result); // Output: Hello, World!
    }
}
