import java.io.IOException;
import java.io.InputStream;

public class VarintReader {
    private final InputStream input;

    public VarintReader(InputStream input) {
        this.input = input;
    }

    public long readRawVarint64() throws IOException {
        long result = 0;
        int shift = 0;
        while (true) {
            if (shift >= 64) {
                throw new IOException("Encountered a malformed varint.");
            }
            int b = input.read();
            if (b == -1) {
                throw new IOException("Unexpected end of input.");
            }
            result |= (long) (b & 0x7F) << shift;
            if ((b & 0x80) == 0) {
                break;
            }
            shift += 7;
        }
        return result;
    }

    public static void main(String[] args) {
        // Example usage
        byte[] varintBytes = {0x96, 0x01}; // Example varint encoding of 150
        VarintReader reader = new VarintReader(new java.io.ByteArrayInputStream(varintBytes));
        try {
            long value = reader.readRawVarint64();
            System.out.println("Read value: " + value);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}
