public class FrameStack {

    private Stack<String> outputFrameStack = new Stack<>();

    /** 
     * Pops as many abstract types from the output frame stack as described by the given descriptor.
     * @param descriptor a type or method descriptor (in which case its argument types are popped).
     */
    private void pop(final String descriptor) {
        if (descriptor.startsWith("(")) {
            // It's a method descriptor, extract the argument types
            int end = descriptor.indexOf(")");
            String argumentTypes = descriptor.substring(1, end);
            int index = 0;
            while (index < argumentTypes.length()) {
                char c = argumentTypes.charAt(index);
                switch (c) {
                    case 'B': case 'C': case 'D': case 'F': case 'I': case 'S': case 'Z':
                        // Single-slot types
                        outputFrameStack.pop();
                        index++;
                        break;
                    case 'J': case 'D':
                        // Double-slot types
                        outputFrameStack.pop();
                        outputFrameStack.pop();
                        index++;
                        break;
                    case 'L':
                        // Object type, read until ';'
                        int semicolonIndex = argumentTypes.indexOf(';', index);
                        if (semicolonIndex != -1) {
                            outputFrameStack.pop();
                            index = semicolonIndex + 1;
                        } else {
                            throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
                        }
                        break;
                    case '[':
                        // Array type, treat as object
                        outputFrameStack.pop();
                        index++;
                        break;
                    default:
                        throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
                }
            }
        } else {
            // It's a type descriptor
            switch (descriptor) {
                case "B": case "C": case "D": case "F": case "I": case "S": case "Z":
                    outputFrameStack.pop();
                    break;
                case "J": case "D":
                    outputFrameStack.pop();
                    outputFrameStack.pop();
                    break;
                case "L":
                    // Object type, read until ';'
                    if (descriptor.endsWith(";")) {
                        outputFrameStack.pop();
                    } else {
                        throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
                    }
                    break;
                case "[":
