import java.io.DataOutput;
import java.io.IOException;

public class LinkedBufferWriter {

    public static class LinkedBuffer {
        byte[] buffer;
        LinkedBuffer next;
        int start;
        int offset;

        public LinkedBuffer(byte[] buffer, LinkedBuffer next, int start, int offset) {
            this.buffer = buffer;
            this.next = next;
            this.start = start;
            this.offset = offset;
        }
    }

    /** 
     * Writes the contents of the  {@link LinkedBuffer} into the {@link DataOutput}.
     * @return the total content size of the buffer.
     */
    public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
        int totalSize = 0;
        while (node != null) {
            int size = node.offset - node.start;
            out.write(node.buffer, node.start, size);
            totalSize += size;
            node = node.next;
        }
        return totalSize;
    }

    public static void main(String[] args) throws IOException {
        // Example usage
        byte[] buffer1 = {0, 1, 2, 3, 4};
        byte[] buffer2 = {5, 6, 7, 8, 9};
        LinkedBuffer node1 = new LinkedBuffer(buffer1, null, 0, 5);
        LinkedBuffer node2 = new LinkedBuffer(buffer2, null, 0, 5);
        node1.next = node2;

        java.io.ByteArrayOutputStream byteArrayOutputStream = new java.io.ByteArrayOutputStream();
        int totalSize = writeTo(byteArrayOutputStream, node1);
        System.out.println("Total content size: " + totalSize);
    }
}
