            if (i < currentFrame.size()) {
                String type = currentFrame.get(i);
                // Assuming a simple mapping for demonstration purposes
                switch (type) {
                    case "int":
                        stackMapTableEntries.add("Integer");
                        break;
                    case "boolean":
                        stackMapTableEntries.add("Boolean");
                        break;
                    case "double":
                        stackMapTableEntries.add("Double");
                        break;
                    case "float":
                        stackMapTableEntries.add("Float");
                        break;
                    case "long":
                        stackMapTableEntries.add("Long");
                        break;
                    default:
                        stackMapTableEntries.add("Object");
                        break;
                }
            }
        }
