import java.util.Arrays;

public class PrimeUtil {

    public static int nextPrime(int desiredCapacity) {
        if (desiredCapacity <= 1) {
            return 2;
        }

        int candidate = (desiredCapacity % 2 == 0) ? desiredCapacity + 1 : desiredCapacity;
        while (!isPrime(candidate)) {
            candidate += 2;
        }

        if (desiredCapacity >= 1000 && candidate > desiredCapacity * 1.11) {
            candidate = findClosePrime(desiredCapacity);
        }

        return candidate;
    }

    private static boolean isPrime(int number) {
        if (number <= 1) {
            return false;
        }
        if (number <= 3) {
            return true;
        }
        if (number % 2 == 0 || number % 3 == 0) {
            return false;
        }
        for (int i = 5; i * i <= number; i += 6) {
            if (number % i == 0 || number % (i + 2) == 0) {
                return false;
            }
        }
        return true;
    }

    private static int findClosePrime(int desiredCapacity) {
        int lowerBound = (int) (desiredCapacity * 0.89);
        int upperBound = (int) (desiredCapacity * 1.11);

        for (int i = desiredCapacity; i <= upperBound; i++) {
            if (isPrime(i)) {
                return i;
            }
        }

        for (int i = desiredCapacity - 1; i >= lowerBound; i--) {
            if (isPrime(i)) {
                return i;
            }
        }

        return desiredCapacity; // Fallback, should not reach here
    }

    public static void main(String[] args) {
        System.out.println(nextPrime(1000)); // Example usage
    }
}
