public class CharsetTranslator {

    private static final Map<String, String> mimeToJavaCharsetMap;

    static {
        mimeToJavaCharsetMap = new HashMap<>();
        mimeToJavaCharsetMap.put("UTF-8", "UTF-8");
        mimeToJavaCharsetMap.put("ISO-8859-1", "ISO-8859-1");
        mimeToJavaCharsetMap.put("US-ASCII", "US-ASCII");
        mimeToJavaCharsetMap.put("UTF-16", "UTF-16");
        mimeToJavaCharsetMap.put("UTF-16BE", "UTF-16BE");
        mimeToJavaCharsetMap.put("UTF-16LE", "UTF-16LE");
        mimeToJavaCharsetMap.put("ISO-8859-15", "ISO-8859-15");
        // Add more mappings as needed
    }

    private static String javaCharset(String charset) {
        if (charset == null) {
            return null;
        }
        String javaCharset = mimeToJavaCharsetMap.get(charset.toUpperCase());
        if (javaCharset == null) {
            // Fallback to using Charset.forName, which might throw an exception if the charset is not supported
            try {
                Charset.forName(charset);
                return charset;
            } catch (IllegalArgumentException e) {
                return null;
            }
        }
        return javaCharset;
    }

    public static void main(String[] args) {
        System.out.println(javaCharset("UTF-8")); // Output: UTF-8
        System.out.println(javaCharset("ISO-8859-1")); // Output: ISO-8859-1
        System.out.println(javaCharset("unknown")); // Output: null
    }
