        return isActive;
    }

    public void setActive(boolean active) {
        isActive = active;
    }
}

public class CategoryTree {
    private Category root;

    public CategoryTree(Category root) {
        this.root = root;
    }

    protected int removeUnusedNodes() {
        return removeInactiveNodes(root);
    }

    private int removeInactiveNodes(Category node) {
        int removedCount = 0;
        List<Category> activeChildren = new ArrayList<>();

        for (Category child : node.getChildren()) {
            if (child.isActive()) {
                activeChildren.add(child);
                removedCount += removeInactiveNodes(child);
            } else {
                removedCount++;
            }
        }

        node.getChildren().clear();
        node.getChildren().addAll(activeChildren);

        return removedCount;
    }

    public static void main(String[] args) {
        Category root = new Category("Root", true);
        Category child1 = new Category("Child1", true);
        Category child2 = new Category("Child2", false);
        Category child3 = new Category("Child3", true);
        Category child4 = new Category("Child4", false);

        root.addChild(child1);
        root.addChild(child2);
        child1.addChild(child3);
        child1.addChild(child4);

        CategoryTree tree = new CategoryTree(root);
        int removedNodes = tree.removeUnusedNodes();
        System.out.println("Removed nodes: " + removedNodes);
    }
}
