import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class DotIdentifierUnescaper {

    /** 
     * Unescape a string DOT identifier.
     * @param input the input
     * @return the unescaped output
     */
    private String unescapeId(String input) {
        if (input == null) {
            return null;
        }
        // Assuming escaping is done with backslashes, e.g., "\." -> "."
        Pattern pattern = Pattern.compile("\\\\(.)");
        Matcher matcher = pattern.matcher(input);
        StringBuffer sb = new StringBuffer();
        while (matcher.find()) {
            matcher.appendReplacement(sb, matcher.group(1));
        }
        matcher.appendTail(sb);
        return sb.toString();
    }

    public static void main(String[] args) {
        DotIdentifierUnescaper unescaper = new DotIdentifierUnescaper();
        String escapedId = "example\\\\.com";
        String unescapedId = unescaper.unescapeId(escapedId);
        System.out.println("Unescaped ID: " + unescapedId);
    }
}
