import java.util.List;
import java.util.NoSuchElementException;

class ListNodeImpl<E> {
    E item;
    ListNodeImpl<E> next;
    ListNodeImpl<E> prev;

    ListNodeImpl(ListNodeImpl<E> prev, E element, ListNodeImpl<E> next) {
        this.item = element;
        this.next = next;
        this.prev = prev;
    }
}

public class LinkedListImplementation<E> {
    private ListNodeImpl<E> first;
    private ListNodeImpl<E> last;
    private int size;

    private boolean unlink(ListNodeImpl<E> node) {
        if (node == null) {
            return false;
        }

        E element = node.item;
        ListNodeImpl<E> next = node.next;
        ListNodeImpl<E> prev = node.prev;

        if (prev == null) {
            first = next;
        } else {
            prev.next = next;
            node.prev = null;
        }

        if (next == null) {
            last = prev;
        } else {
            next.prev = prev;
            node.next = null;
        }

        node.item = null;
        size--;
        return true;
    }

    public static void main(String[] args) {
        LinkedListImplementation<String> list = new LinkedListImplementation<>();
        ListNodeImpl<String> node1 = new ListNodeImpl<>(null, "first", null);
        ListNodeImpl<String> node2 = new ListNodeImpl<>(node1, "second", null);
        node1.next = node2;
        list.first = node1;
        list.last = node2;
        list.size = 2;

        list.unlink(node2);
        System.out.println(list.size); // Should print 1
    }
}
