import java.io.IOException;
import java.io.Reader;

public class TokenParser {
    private final Reader reader;

    public TokenParser(Reader reader) {
        this.reader = reader;
    }

    private String parseToken(final char[] terminators) throws IOException {
        StringBuilder token = new StringBuilder();
        int intChar;
        while ((intChar = reader.read()) != -1) {
            char currentChar = (char) intChar;
            boolean isTerminator = false;
            for (char terminator : terminators) {
                if (currentChar == terminator) {
                    isTerminator = true;
                    break;
                }
            }
            if (isTerminator) {
                break;
            }
            token.append(currentChar);
        }
        return token.toString();
    }

    public static void main(String[] args) {
        // Example usage
        String input = "exampleToken;moreData";
        char[] terminators = {';', ' '};
        try (Reader reader = new java.io.StringReader(input)) {
            TokenParser parser = new TokenParser(reader);
            String token = parser.parseToken(terminators);
            System.out.println("Parsed token: " + token);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}
