public class Abbreviator {
    /** 
     * Abbreviate name.
     * @param buf buffer to append abbreviation.
     * @param nameStart start of name to abbreviate.
     */
    public void abbreviate(final int nameStart, final StringBuffer buf) {
        if (buf == null || nameStart < 0 || nameStart >= buf.length()) {
            return;
        }
        String name = buf.substring(nameStart);
        StringTokenizer tokenizer = new StringTokenizer(name, " ");
        buf.delete(nameStart, buf.length());
        while (tokenizer.hasMoreTokens()) {
            String token = tokenizer.nextToken();
            if (token.length() > 0) {
                buf.append(token.charAt(0)).append('.');
            }
        }
    }

    public static void main(String[] args) {
        Abbreviator abbreviator = new Abbreviator();
        StringBuffer buffer = new StringBuffer("John Doe Smith");
        abbreviator.abbreviate(5, buffer);
        System.out.println(buffer.toString()); // Output: John D.S.
    }
}
