import java.util.Stack;

public class FrameStack {

    private Stack<String> outputFrameStack;

    public FrameStack() {
        this.outputFrameStack = new Stack<>();
    }

    /** 
     * Pops as many abstract types from the output frame stack as described by the given descriptor.
     * @param descriptor a type or method descriptor (in which case its argument types are popped).
     */
    private void pop(final String descriptor) {
        if (descriptor == null || descriptor.isEmpty()) {
            return;
        }

        if (descriptor.startsWith("(")) {
            // It's a method descriptor, parse the argument types
            int endIndex = descriptor.indexOf(')');
            if (endIndex != -1) {
                String arguments = descriptor.substring(1, endIndex);
                parseAndPopArguments(arguments);
            }
        } else {
            // It's a type descriptor, pop one type
            popType(descriptor);
        }
    }

    private void parseAndPopArguments(String arguments) {
        int index = 0;
        while (index < arguments.length()) {
            char type = arguments.charAt(index);
            switch (type) {
                case 'B':
                case 'C':
                case 'D':
                case 'F':
                case 'I':
                case 'J':
                case 'S':
                case 'Z':
                    popType(String.valueOf(type));
                    index++;
                    break;
                case 'L': // Object type
                    index = arguments.indexOf(';', index) + 1;
                    popType("L");
                    break;
                case '[': // Array type
                    popType("[");
                    index++;
                    break;
                default:
                    index++;
                    break;
            }
        }
    }

    private void popType(String typeDescriptor) {
        if (!outputFrameStack.isEmpty()) {
            outputFrameStack.pop();
        }
    }

    public static void main(String[] args) {
        FrameStack frameStack = new FrameStack();
        // Example usage
        frameStack.outputFrameStack.push("int");
        frameStack.outputFrameStack.push("double");
        frameStack.outputFrameStack.push("java/lang/String");
        frameStack.pop("(IDLjava/lang/String;)V");
        System.out.println(frameStack.outputFrameStack); // Should be empty
    }
}
