import java.io.File;

public class FilenameUtils {

    public static int indexOfLastSeparator(String filename) {
        if (filename == null) {
            return -1;
        }
        int lastUnixPos = filename.lastIndexOf(File.separatorChar);
        int lastWindowsPos = filename.lastIndexOf('\\');
        return Math.max(lastUnixPos, lastWindowsPos);
    }

    public static int indexOfExtension(String filename) {
        if (filename == null) {
            return -1;
        }
        int lastSeparatorIndex = indexOfLastSeparator(filename);
        int lastDotIndex = filename.lastIndexOf('.');
        if (lastDotIndex == -1 || lastSeparatorIndex > lastDotIndex) {
            return -1;
        }
        return lastDotIndex;
    }

    public static void main(String[] args) {
        // Example usage
        System.out.println(indexOfExtension("example/file.txt")); // Output: 11
        System.out.println(indexOfExtension("example\\file.txt")); // Output: 11
        System.out.println(indexOfExtension("example/file")); // Output: -1
        System.out.println(indexOfExtension("example.file/")); // Output: -1
        System.out.println(indexOfExtension("example/file.")); // Output: 11
        System.out.println(indexOfExtension("example/file.name.txt")); // Output: 16
        System.out.println(indexOfExtension(null)); // Output: -1
    }
}
