import java.util.concurrent.TimeUnit;

public class CacheUtil {
    /** 
     * @param timestamp        of current time
     * @param expiredThreshold represents the duration between last update time and the time point removing from cache.
     * @return true means this metrics should be removed from cache.
     */
    public boolean isExpired(long lastUpdateTime, long expiredThreshold) {
        long currentTime = System.currentTimeMillis();
        return (currentTime - lastUpdateTime) > expiredThreshold;
    }

    public static void main(String[] args) {
        CacheUtil cacheUtil = new CacheUtil();
        long lastUpdateTime = System.currentTimeMillis() - TimeUnit.MINUTES.toMillis(11); // Example: last updated 11 minutes ago
        long expiredThreshold = TimeUnit.MINUTES.toMillis(10); // Example: threshold is 10 minutes
        System.out.println(cacheUtil.isExpired(lastUpdateTime, expiredThreshold)); // Should print true
    }
}
