import java.util.*;

class Node {
    private String label;

    public Node(String label) {
        this.label = label;
    }

    public String getLabel() {
        return label;
    }
}

class Edge {
    private Node from;
    private Node to;

    public Edge(Node from, Node to) {
        this.from = from;
        this.to = to;
    }

    public Node getFrom() {
        return from;
    }

    public Node getTo() {
        return to;
    }
}

class Graph {
    private List<Node> nodes;
    private Iterator<Node> nodeIterator;

    public Graph(List<Node> nodes) {
        this.nodes = nodes;
        this.nodeIterator = nodes.iterator();
    }

    public Edge edgeToNext() {
        if (!nodeIterator.hasNext()) {
            return null;
        }
        Node current = nodeIterator.next();
        Node next = nodeIterator.hasNext() ? nodeIterator.next() : null;
        if (next == null) {
            nodeIterator = nodes.iterator(); // Reset iterator if end is reached
            next = nodeIterator.next();
        }
        return new Edge(current, next);
    }
}

public class Main {
    public static void main(String[] args) {
        List<Node> nodes = Arrays.asList(new Node("A"), new Node("B"), new Node("C"));
        Graph graph = new Graph(nodes);
        System.out.println(graph.edgeToNext().getFrom().getLabel() + " -> " + graph.edgeToNext().getTo().getLabel());
    }
}
