import java.io.IOException;
import java.io.InputStream;

public class ProtocolMessageParser {
    private final InputStream input;

    public ProtocolMessageParser(InputStream input) {
        this.input = input;
    }

    public int readTag() throws IOException {
        if (input.available() == 0) {
            return 0;
        }
        int tag = input.read();
        if (tag == -1) {
            return 0;
        }
        return tag;
    }

    public static void main(String[] args) {
        // Example usage
        byte[] data = {0x08, 0x10, 0x1A}; // Example data with tags
        ProtocolMessageParser parser = new ProtocolMessageParser(new java.io.ByteArrayInputStream(data));
        try {
            int tag = parser.readTag();
            while (tag != 0) {
                System.out.println("Read tag: " + tag);
                tag = parser.readTag();
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}
